package kindergarten

import (
	"errors"
	"sort"
)

var (
	errDiagramFormat   = errors.New("diagram must start with a newline and contain two rows")
	errMismatchedRows  = errors.New("diagram rows must be the same length")
	errOddNumberOfCups = errors.New("diagram must have an even number of cups")
	errInvalidCupCode  = errors.New("invalid cup code in diagram")
	errTooManyChildren = errors.New("there are too many children")
	errDuplicateName   = errors.New("duplicate child names")
)

// plantNames maps the diagram cup codes to plant names.
var plantNames = map[byte]string{
	'G': "grass",
	'C': "clover",
	'R': "radishes",
	'V': "violets",
}

// Garden represents a kindergarten garden: two rows of cups, with the
// cups assigned to the children in alphabetical order of their names.
type Garden struct {
	rows     [2]string
	children []string // sorted copy of the names given to NewGarden
}

// NewGarden parses the diagram and returns a Garden.
//
// The diagram argument starts each row with a '\n'.  This allows Go's
// raw string literals to present diagrams in source code nicely as two
// rows flush left, for example,
//
//	diagram := `
//	VVCCGG
//	VVCCGG`
//
// The children argument is not modified; the garden keeps its own
// sorted copy.
func NewGarden(diagram string, children []string) (*Garden, error) {
	if len(diagram) < 2 || diagram[0] != '\n' {
		return nil, errDiagramFormat
	}
	rest := diagram[1:]
	idx := indexByte(rest, '\n')
	if idx < 0 {
		return nil, errDiagramFormat
	}
	row1 := rest[:idx]
	row2 := rest[idx+1:]
	if idx+1 != len(rest) {
		return nil, errDiagramFormat
	}
	if len(row1) != len(row2) {
		return nil, errMismatchedRows
	}
	if len(row1)%2 != 0 {
		return nil, errOddNumberOfCups
	}
	for i := 0; i < len(row1); i++ {
		if _, ok := plantNames[row1[i]]; !ok {
			return nil, errInvalidCupCode
		}
		if _, ok := plantNames[row2[i]]; !ok {
			return nil, errInvalidCupCode
		}
	}
	if len(children) > len(row1)/2 {
		return nil, errTooManyChildren
	}
	seen := make(map[string]bool, len(children))
	for _, child := range children {
		if seen[child] {
			return nil, errDuplicateName
		}
		seen[child] = true
	}
	sorted := make([]string, len(children))
	copy(sorted, children)
	sort.Strings(sorted)
